package com.mezze.language.interpreter.nodes

import com.mezze.language.ast.*
import com.mezze.language.interpreter.*
import com.mezze.language.interpreter.continuations.*
import com.oracle.truffle.api.frame.VirtualFrame

/**
 * Truffle node for executing compiler-generated state machines.
 *
 * This node executes StateMachineExpressions that have been generated by
 * the ContinuationTransformer during compilation.
 */
class StateMachineNode(
    private val stateMachineExpr: StateMachineExpression,
    private val converter: ASTToTruffleConverter
) : MezzeNode() {

    override fun execute(frame: VirtualFrame): MezzeValue {
        // Build the runtime state machine from the AST representation
        val builder = ContinuationStateMachineBuilder()

        // CRITICAL: Convert all state expressions FIRST before getting the frame descriptor
        // This ensures all variables referenced in states are registered in the converter
        val convertedStates = mutableListOf<Pair<Any, MezzeNode>>()

        for (state in stateMachineExpr.states) {
            when (state) {
                is ComputeState -> {
                    // Convert the computation expression to a Truffle node

                    val computeNode = try {
                        converter.convertExpression(state.computation)
                    } catch (e: Exception) {

                        e.printStackTrace()
                        throw RuntimeException("Failed to convert ComputeState expression: ${state.computation}", e)
                    }




                    if (computeNode == null) {
                        throw RuntimeException("FATAL: convertExpression returned null for ${state.computation}. This should be impossible!")
                    }
                    convertedStates.add(state to computeNode)
                }
                is YieldState -> {
                    val valueNode = converter.convertExpression(state.valueExpression)
                    convertedStates.add(state to valueNode)
                }
                is CompleteState -> {


                    val resultNode = converter.convertExpression(state.resultExpression)

                    convertedStates.add(state to resultNode)
                }
            }
        }

        // NOW get the frame descriptor after all variables are registered
        val frameDescriptor = converter.getFrameDescriptor()

        // Build the state machine with the converted nodes
        // CRITICAL: Create FRESH frames for each state execution to support multishot continuations
        for ((state, node) in convertedStates) {

            when (state) {
                is ComputeState -> {
                    val computeNode = node


                    builder.addComputeState { machine, input ->
                        // Create a FRESH frame for this execution (critical for multishot)
                        val numSlots = frameDescriptor.numberOfSlots.coerceAtLeast(2)
                        val args = Array<Any?>(numSlots) { idx ->
                            when (idx) {
                                0 -> MezzeRecord(emptyMap())  // parameters
                                1 -> emptyMap<String, MezzeValue>()  // closure variables
                                else -> com.mezze.language.interpreter.MezzeNull  // other slots
                            }
                        }
                        val freshFrame = com.oracle.truffle.api.Truffle.getRuntime()
                            .createMaterializedFrame(args, frameDescriptor)

                        // CRITICAL: Write the input value to the special __state_machine_input__ slot
                        // This allows binding states to access the value passed from previous states
                        // When fork resumes a continuation, it passes {value = <actual_value>}
                        // We need to extract the actual value from the record
                        val inputSlot = converter.getVariableSlots()["__state_machine_input__"]
                        if (inputSlot != null) {
                            val actualInput = if (input is MezzeRecord && input.fields.containsKey("value")) {
                                // Fork passes {value = <actual>}, extract it
                                val extracted = input.fields["value"]!!

                                extracted
                            } else {
                                // Direct value (from state-to-state transitions)

                                input
                            }

                            freshFrame.setObject(inputSlot, actualInput)
                        }

                        // Populate frame with captured locals from the machine
                        // CRITICAL: Skip __state_machine_input__ since it comes from the input parameter, not captured locals

                        for ((varName, varValue) in machine.capturedLocals) {
                            // CRITICAL: Don't overwrite __state_machine_input__ - it was set from the input parameter above
                            if (varName == "__state_machine_input__") {

                                continue
                            }

                            val slot = converter.getVariableSlots()[varName]
                            if (slot != null) {
                                val valueStr = (varValue as? MezzeInt)?.value?.toString() ?: varValue::class.simpleName

                                freshFrame.setObject(slot, varValue)
                            }
                        }

                        // Execute the computation node with the fresh frame

                        val result = computeNode.execute(freshFrame)


                        // CRITICAL: Check if result is a suspended continuation (for early return, exception handling)
                        // If suspended, skip variable capture and return immediately
                        // This implements early return semantics for Return effect and exception handling
                        if (result !is com.mezze.language.interpreter.MezzeContinuationSuspended) {
                            // Only capture variables if we're NOT suspending (normal execution flow)

                            val updatedLocals = mutableMapOf<String, MezzeValue>()
                            for ((varName, slot) in converter.getVariableSlots()) {
                                val value = freshFrame.getObject(slot) as? MezzeValue
                                if (value != null && value !is MezzeNull) {
                                    val valueStr = (value as? MezzeInt)?.value?.toString() ?: value::class.simpleName

                                    updatedLocals[varName] = value
                                }
                            }


                            // Pass updated locals to the state machine via ThreadLocal
                            ContinuationStateMachine.setUpdatedLocals(updatedLocals)
                        } else {

                        }

                        result
                    }
                }

                is YieldState -> {
                    val valueNode = node

                    builder.addYieldState { machine, input ->
                        // Create a FRESH frame for this execution (critical for multishot)
                        val numSlots = frameDescriptor.numberOfSlots.coerceAtLeast(2)
                        val args = Array<Any?>(numSlots) { idx ->
                            when (idx) {
                                0 -> MezzeRecord(emptyMap())  // parameters
                                1 -> emptyMap<String, MezzeValue>()  // closure variables
                                else -> com.mezze.language.interpreter.MezzeNull  // other slots
                            }
                        }
                        val freshFrame = com.oracle.truffle.api.Truffle.getRuntime()
                            .createMaterializedFrame(args, frameDescriptor)

                        // Populate frame with captured locals
                        for ((varName, varValue) in machine.capturedLocals) {
                            val slot = converter.getVariableSlots()[varName]
                            if (slot != null) {
                                freshFrame.setObject(slot, varValue)
                            }
                        }

                        // Evaluate the value expression
                        valueNode.execute(freshFrame)
                    }
                }

                is CompleteState -> {
                    val resultNode = node

                    builder.addCompleteState { machine, input ->



                        // Create a FRESH frame for this execution (critical for multishot)
                        val numSlots = frameDescriptor.numberOfSlots.coerceAtLeast(2)
                        val args = Array<Any?>(numSlots) { idx ->
                            when (idx) {
                                0 -> MezzeRecord(emptyMap())  // parameters
                                1 -> emptyMap<String, MezzeValue>()  // closure variables
                                else -> com.mezze.language.interpreter.MezzeNull  // other slots
                            }
                        }
                        val freshFrame = com.oracle.truffle.api.Truffle.getRuntime()
                            .createMaterializedFrame(args, frameDescriptor)

                        // Populate frame with captured locals
                        // CRITICAL: Skip __state_machine_input__ since it's a special binding variable


                        for ((varName, varValue) in machine.capturedLocals) {
                            // Skip __state_machine_input__ - it's only used for binding states
                            if (varName == "__state_machine_input__") {

                                continue
                            }

                            val slot = converter.getVariableSlots()[varName]

                            if (slot != null) {
                                val valueStr = (varValue as? MezzeInt)?.value?.toString() ?: varValue::class.simpleName

                                freshFrame.setObject(slot, varValue)
                            } else {

                            }
                        }

                        // Evaluate the result expression
                        val result = resultNode.execute(freshFrame)

                        result
                    }
                }
            }
        }

        // Build the state machine with captured variables from the frame
        // CRITICAL FIX: Capture ALL variables from converter, not just stateMachineExpr.capturedVariables
        // This ensures intermediate variables are preserved for multishot fork operations
        val capturedLocals = mutableMapOf<String, MezzeValue>()
        val incomingFrameSlots = frame.frameDescriptor.numberOfSlots
        for ((varName, slot) in converter.getVariableSlots()) {
            // Only read slots that exist in the incoming frame
            if (slot < incomingFrameSlots) {
                val value = frame.getObject(slot) as? MezzeValue
                if (value != null && value !is MezzeNull) {
                    capturedLocals[varName] = value
                }
            }
        }

        val stateMachine = builder.build(capturedLocals)

        // Execute the state machine with MezzeNull as initial input
        return stateMachine.execute(MezzeNull)
    }
}
